  return Buffer.from(value, 'hex').toString('utf8');
}

function compile(source, id) {
  try {
    return new Function(`"use strict";\n${source}\nreturn benchmark;`)();
  } catch (error) {
    fail(id, `could not compile source: ${error.message}`, 1);
